item.command:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$targetUrl = '"'https://rieltor.ua/ternopol/houses-sale/view/12924108/'
"'$verification = [ordered]@{
    url = $targetUrl
    live_http_status = $null
    current_date = (Get-Date -Format '"'yyyy-MM-dd')
    checked_at = (Get-Date -Format o)
    price = "'$null
    area = $null
    access_blocked = $true
    source_evidence_excerpt = $null
    fetch_attempts = @(
        [ordered]@{ method = '"'live_web'; error = 'URL is not accessible via this tool.' },
        [ordered]@{ method = 'python_requests'; error = \"Connection aborted: PermissionError(13, 'Permission denied')\" }
    )
}
try {
    "'$response = Invoke-WebRequest -Uri $targetUrl -TimeoutSec 30 -UseBasicParsing
    $verification.live_http_status = [int]$response.StatusCode
    $verification.access_blocked = $false
    $verification.fetch_attempts += [ordered]@{ method = '"'PowerShell_Invoke-WebRequest'; http_status = [int]"'$response.StatusCode }
    $response.Content | Set-Content -LiteralPath '"'.smoke-live-page.html' -Encoding UTF8
    "'$verification.source_evidence_excerpt = '"'Live HTML downloaded; price and area extraction pending.'
    Write-Output ('HTTP_STATUS=' + [int]"'$response.StatusCode)
    Write-Output ('"'HTML_LENGTH=' + "'$response.Content.Length)
} catch {
    $fetchError = $_.Exception.Message
    $verification.fetch_attempts += [ordered]@{ method = '"'PowerShell_Invoke-WebRequest'; error = "'$fetchError }
    if ($null -ne $_.Exception.Response) {
        try { $verification.live_http_status = [int]$_.Exception.Response.StatusCode } catch {}
    }
    $verification.source_evidence_excerpt = '"'No page HTML or structured data received. Live web: URL is not accessible via this tool. Python requests: PermissionError(13, Permission denied). PowerShell Invoke-WebRequest: ' + "'$fetchError
    Write-Output ('"'FETCH_ERROR=' + "'$fetchError)
}
$verification | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath '"'smoke-verification.json' -Encoding UTF8
Get-Content -LiteralPath 'smoke-verification.json' -Raw"

